     1→package com.cowave.search.inbound_adapter.handler
     2→
     3→import com.cowave.search.inbound_adapter.handler.dto.ConsumerCallback
     4→import com.cowave.search.inbound_adapter.handler.dto.ConsumerGroupOffsetSnapshot
     5→import com.cowave.shared.utils.logger
     6→import org.springframework.kafka.listener.ConsumerSeekAware
     7→import org.springframework.stereotype.Component
     8→import java.util.concurrent.ConcurrentHashMap
     9→import java.util.concurrent.locks.ReentrantLock
    10→
    11→/**
    12→ * Consumer offset을 중앙 관리하는 컴포넌트
    13→ * 멀티스레드 안전성을 위해 요청을 큐에 저장하고 idle 상태에서 처리
    14→ */
    15→@Component
    16→class ConsumerCallbackManager {
    17→    private val logger by logger()
    18→    private val consumerCallbacks = ConcurrentHashMap<String, ConsumerCallback>()
    19→    private val lock = ReentrantLock()
    20→
    21→    /**
    22→     * ConsumerGroupOffsetInfo를 받아서 일괄 처리
    23→     */
    24→    fun requestToSeek(offsetSnapshot: ConsumerGroupOffsetSnapshot) {
    25→        logger.info { "[ConsumerManager] Start to set offset. " +
    26→                "groupId=[${offsetSnapshot.groupId}], topic=[${offsetSnapshot.topic}], " +
    27→                "partition count=[${offsetSnapshot.partitions.count()}]" }
    28→
    29→        if (lock.tryLock()) {
    30→            try {
    31→                // offset seek 대상인 topic의 컨슈머를 찾음
    32→                val targets = consumerCallbacks.values.filter { it.topic == offsetSnapshot.topic }
    33→                    .associateBy { it.uniqueKey }
    34→
    35→                if (targets.isEmpty()) {
    36→                    logger.info { "[ConsumerManager] This listener does not have any consumer callback." }
    37→                    return
    38→                }
    39→
    40→                offsetSnapshot.partitions.forEach { partitionSnapshot ->
    41→                    val key = ConsumerCallback.getUniqueKey(
    42→                        groupId = offsetSnapshot.groupId,
    43→                        topic = offsetSnapshot.topic,
    44→                        partition = partitionSnapshot.partition,
    45→                    )
    46→
    47→                    if (targets.containsKey(key)) {
    48→                        val consumerCallback = targets[key]!!
    49→                        consumerCallback.setSeek(partitionSnapshot.currentOffset)
    50→
    51→                        logger.info { "[ConsumerManager] Offset has been set. " +
    52→                                "groupId=[${consumerCallback.groupId}], topic=[${consumerCallback.topic}], " +
    53→                                "partition=[${consumerCallback.partition}], offset=[${partitionSnapshot.currentOffset}]" }
    54→                    }
    55→                }
    56→            } catch (e: Exception) {
    57→                logger.error(e) { "[ConsumerManager] Offset seek error: ${e.message}" }
    58→            } finally {
    59→                lock.unlock()
    60→                logger.info { "[ConsumerManager] Finished to set offset. " +
    61→                        "groupId=[${offsetSnapshot.groupId}], topic=[${offsetSnapshot.topic}]" }
    62→            }
    63→        } else {
    64→            logger.info { "[ConsumerManager] Skipped to set offset because of lock. " +
    65→                    "groupId=[${offsetSnapshot.groupId}], topic=[${offsetSnapshot.topic}]" }
    66→        }
    67→    }
    68→
    69→    fun getConsumerCallback(
    70→        groupId: String,
    71→        topic: String,
    72→        partition: Int,
    73→    ): ConsumerCallback {
    74→        val key = ConsumerCallback.getUniqueKey(groupId, topic, partition)
    75→        return consumerCallbacks[key] ?: throw NoSuchElementException("No consumer callback found for key: $key")
    76→    }
    77→
    78→    fun getAllConsumerCallbacks(): List<ConsumerCallback> = consumerCallbacks.values.toList()
    79→
    80→    fun register(
    81→        groupId: String,
    82→        topic: String,
    83→        partition: Int,
    84→        callback: ConsumerSeekAware.ConsumerSeekCallback,
    85→    ) {
    86→        val consumerCallback = ConsumerCallback(groupId, topic, partition, callback)
    87→
    88→        if (consumerCallbacks.contains(consumerCallback.uniqueKey)) {
    89→            logger.warn { "[ConsumerManager] Consumer is already registered with ConsumerManager. " +
    90→                    "groupId=[$groupId], topic=[$topic], partition=[$partition]" }
    91→        } else {
    92→            consumerCallbacks[consumerCallback.uniqueKey] = consumerCallback
    93→            logger.info { "[ConsumerManager] Consumer registered with ConsumerManager. " +
    94→                    "groupId=[$groupId], topic=[$topic], partition=[$partition]" }
    95→        }
    96→    }
    97→
    98→    fun revoke(
    99→        groupId: String,
   100→        topic: String,
   101→        partition: Int,
   102→    ) {
   103→        val key = ConsumerCallback.getUniqueKey(groupId, topic, partition)
   104→        consumerCallbacks.remove(key)
   105→
   106→        logger.info { "[ConsumerManager] Consumer revoked from ConsumerManager. " +
   107→                "groupId=[$groupId], topic=[$topic], partition=[$partition]" }
   108→    }
   109→}

