    10→@Service
    11→class CachedProxyApplicationService(
    12→    private val categoryApplicationService: CategoryApplicationService,
    13→    private val brandApplicationService: BrandApplicationService,
    14→    private val manufacturerApplicationService: ManufacturerApplicationService,
    15→    private val mallApplicationService: MallApplicationService,
    16→) {
    17→    fun fetchDependencies(dependencyId: DependencyId): Dependency =
    18→        runBlocking(Dispatchers.IO) {
    19→            val categoriesDeferred =
    20→                async {
    21→                    if (dependencyId.categoryIds.isEmpty()) {
    22→                        emptyMap()
    23→                    } else {
    24→                        categoryApplicationService.getCachedAllByIds(dependencyId.categoryIds)
    25→                    }
    26→                }
    27→            val brandsDeferred =
    28→                async {
    29→                    if (dependencyId.brandIds.isEmpty()) {
    30→                        emptyMap()
    31→                    } else {
    32→                        brandApplicationService.getCachedAllByIds(dependencyId.brandIds)
    33→                    }
    34→                }
    35→            val manufacturersDeferred =
    36→                async {
    37→                    if (dependencyId.manufacturerIds.isEmpty()) {
    38→                        emptyMap()
    39→                    } else {
    40→                        manufacturerApplicationService.getCachedAllByIds(dependencyId.manufacturerIds)
    41→                    }
    42→                }
    43→            val mallsDeferred =
    44→                async {
    45→                    if (dependencyId.mallIds.isEmpty()) {
    46→                        emptyMap()
    47→                    } else {
    48→                        mallApplicationService.getCachedAllByIds(dependencyId.mallIds)
    49→                    }
    50→                }
    51→
    52→            Dependency(
    53→                categories = categoriesDeferred.await(),
    54→                brands = brandsDeferred.await(),
    55→                manufacturers = manufacturersDeferred.await(),
    56→                malls = mallsDeferred.await(),
    57→            )
    58→        }
    59→}

