     8→object ProductMergeStrategy : MergeStrategy<Product> {
     9→    private val logger by logger()
    10→
    11→    override fun merge(documents: List<ChangedData<Product>>): List<ChangedData<Product>> =
    12→        documents
    13→            .groupBy { it.id } // 같은 문서로 그룹핑
    14→            .map { (_, group) ->
    15→                if (group.size == 1) {
    16→                    group.first()
    17→                } else {
    18→                    var isChangedCategory = false
    19→                    var isChangedBrand = false
    20→                    var isChangedManufacturer = false
    21→                    var isChangedMall = false
    22→
    23→                    group
    24→                        .sortedBy { it.offset } // offset 기준으로 정렬
    25→                        .fold(null as ChangedData<Product>?) { acc, current ->
    26→                            when (current.op) {
    27→                                Operation.CREATE -> {
    28→                                    isChangedCategory = true
    29→                                    // Note. product의 brand, manufacturer 연동은 아직 되고 있지 않지만 미리 작업해둠
    30→                                    isChangedBrand = true
    31→                                    isChangedManufacturer = true
    32→                                    isChangedMall = true
    33→                                }
    34→
    35→                                Operation.UPDATE -> {
    36→                                    // Note. update 메시지의 before가 null인 경우 존재
    37→                                    if (current.beforeData != null && current.afterData != null) {
    38→                                        if (current.beforeData.categoryId != current.afterData.categoryId) isChangedCategory = true
    39→                                        if (current.beforeData.brandId != current.afterData.brandId) isChangedBrand = true
    40→                                        if (current.beforeData.manufacturerId !=
    41→                                            current.afterData.manufacturerId
    42→                                        ) {
    43→                                            isChangedManufacturer = true
    44→                                        }
    45→                                        if (current.beforeData.mallId != current.afterData.mallId) isChangedMall = true
    46→                                    }
    47→                                }
    48→
    49→                                Operation.DELETE -> {
    50→                                    isChangedCategory = false
    51→                                    isChangedBrand = false
    52→                                    isChangedManufacturer = false
    53→                                    isChangedMall = false
    54→                                }
    55→                            }
    56→
    57→                            merge(acc, current)
    58→                                .also {
    59→                                    if (it == null) {
    60→                                        // Note. merge result가 null인 경우, acc는 not null이 보장됨
    61→                                        logger.warn { "[ProductMergeStrategy] Unexpected operation. " + diffLog(acc!!, current) }
    62→                                    }
    63→                                }
    64→                        }.apply {
    65→                            this?.shouldFetchCategory = isChangedCategory
    66→                            this?.shouldFetchBrand = isChangedBrand
    67→                            this?.shouldFetchManufacturer = isChangedManufacturer
    68→                            this?.shouldFetchMall = isChangedMall
    69→                        }
    70→                }
    71→            }.filterNotNull()
    72→}
